// plan 10 task 10: destination inbound tokens and CRM reconcile.
// destination_inbound_tokens is a non-RLS auth-plane table (looked up by hash on
// the plain pool); receipts, deliveries and leads are RLS tables: run inside
// tenancy.InWorkspace and keep the explicit workspace predicate.
// Naive timestamp columns (created_at, revoked_at) hold UTC wall time: revoked_at is
// converted with AT TIME ZONE 'UTC', never through the session TimeZone.
func (q *Queries) DestInboundTokenInsert(ctx context.Context, arg DestInboundTokenInsertParams) (pgtype.Timestamp, error) {
	row := q.db.QueryRow(ctx, destInboundTokenInsert,
		arg.ID,
		arg.WorkspaceID,
		arg.DestinationID,
		arg.TokenHash,
		arg.Prefix,
		arg.CreatedBy,
		arg.ExpiresAt,
	)
	var created_at pgtype.Timestamp
	err := row.Scan(&created_at)
	return created_at, err
}

const destInboundTokenLatestActive = `-- name: DestInboundTokenLatestActive :one
SELECT prefix, created_by, created_at, expires_at, last_used_at
FROM destination_inbound_tokens
WHERE workspace_id = $1::text AND destination_id = $2::text
  AND revoked_at IS NULL
ORDER BY created_at DESC, id DESC
LIMIT 1
`

type DestInboundTokenLatestActiveParams struct {
	WorkspaceID   string
	DestinationID string
}

type DestInboundTokenLatestActiveRow struct {
	Prefix     string
	CreatedBy  pgtype.Int4
	CreatedAt  pgtype.Timestamp
	ExpiresAt  pgtype.Timestamptz
	LastUsedAt pgtype.Timestamptz
}

func (q *Queries) DestInboundTokenLatestActive(ctx context.Context, arg DestInboundTokenLatestActiveParams) (DestInboundTokenLatestActiveRow, error) {
	row := q.db.QueryRow(ctx, destInboundTokenLatestActive, arg.WorkspaceID, arg.DestinationID)
	var i DestInboundTokenLatestActiveRow
	err := row.Scan(
		&i.Prefix,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.ExpiresAt,
		&i.LastUsedAt,
	)
	return i, err
}

const destInboundTokenStamp = `-- name: DestInboundTokenStamp :one
UPDATE destination_inbound_tokens SET last_used_at = $1::timestamptz
WHERE id = $2::text AND destination_id = $3::text
  AND revoked_at IS NULL AND expires_at IS NOT NULL AND expires_at > $1::timestamptz
RETURNING workspace_id
`

type DestInboundTokenStampParams struct {
	Now           pgtype.Timestamptz
	ID            string
	DestinationID string
}

// Atomic recheck of revocation, destination binding and expiry while stamping.
func (q *Queries) DestInboundTokenStamp(ctx context.Context, arg DestInboundTokenStampParams) (string, error) {
	row := q.db.QueryRow(ctx, destInboundTokenStamp, arg.Now, arg.ID, arg.DestinationID)
	var workspace_id string
	err := row.Scan(&workspace_id)
	return workspace_id, err
}

const destInboundTokensRevokeActive = `-- name: DestInboundTokensRevokeActive :execrows
UPDATE destination_inbound_tokens SET revoked_at = ($1::timestamptz AT TIME ZONE 'UTC')
WHERE workspace_id = $2::text AND destination_id = $3::text
  AND revoked_at IS NULL
`

type DestInboundTokensRevokeActiveParams struct {
	Now           pgtype.Timestamptz
	WorkspaceID   string
	DestinationID string
}

func (q *Queries) DestInboundTokensRevokeActive(ctx context.Context, arg DestInboundTokensRevokeActiveParams) (int64, error) {
	result, err := q.db.Exec(ctx, destInboundTokensRevokeActive, arg.Now, arg.WorkspaceID, arg.DestinationID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
